struct ICONSMEntry { const char* name; const uint16_t* data; };
static const ICONSMEntry ICONSM_TABLE[] = {
  { "clear-day", ICONSM_CLEAR_DAY },
  { "clear-night", ICONSM_CLEAR_NIGHT },
  { "cloudy", ICONSM_CLOUDY },
  { "drizzle", ICONSM_DRIZZLE },
  { "extreme-rain", ICONSM_EXTREME_RAIN },
  { "fog", ICONSM_FOG },
  { "light-rain", ICONSM_LIGHT_RAIN },
  { "n_a", ICONSM_N_A },
  { "partly-cloudy-day", ICONSM_PARTLY_CLOUDY_DAY },
  { "partly-cloudy-night", ICONSM_PARTLY_CLOUDY_NIGHT },
  { "rain", ICONSM_RAIN },
  { "sleet", ICONSM_SLEET },
  { "snow", ICONSM_SNOW },
  { "thunderstorm", ICONSM_THUNDERSTORM },
  { "unknown", ICONSM_UNKNOWN },
};
static const int ICONSM_COUNT = sizeof(ICONSM_TABLE)/sizeof(ICONSM_TABLE[0]);

// Tra icon theo ten file (khong .bmp). Tra ve nullptr neu khong co.
static inline const uint16_t* weatherIconSmByName(const char* name) {
  for (int i = 0; i < ICONSM_COUNT; i++)
    if (strcmp(ICONSM_TABLE[i].name, name) == 0) return ICONSM_TABLE[i].data;
  return nullptr;
}
